diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..44456eb 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -7,11 +7,51 @@ export interface Record {
 }

 export const project = (records: readonly Record[]): string => {
+  const extractKeywords = (text: string): Set<string> => {
+    const words = text.match(/\b\w+\b/g) || [];
+    return new Set(words.filter(w => w.length > 3).map(w => w.toLowerCase()));
+  };
+
+  const jaccardSimilarity = (s1: Set<string>, s2: Set<string>): number => {
+    const intersection = new Set([...s1].filter(x => s2.has(x)));
+    const union = new Set([...s1, ...s2]);
+    return union.size === 0 ? 0 : intersection.size / union.size;
+  };
+
+  const deduplicateBySemanticSimilarity = (items: string[]): string[] => {
+    if (items.length <= 1) return items;
+
+    const groups: Set<number>[] = [];
+    const assigned = new Set<number>();
+    const SIMILARITY_THRESHOLD = 0.2;
+
+    for (let i = 0; i < items.length; i++) {
+      if (assigned.has(i)) continue;
+
+      const group = new Set([i]);
+      assigned.add(i);
+      const keywords_i = extractKeywords(items[i]);
+
+      for (let j = i + 1; j < items.length; j++) {
+        if (assigned.has(j)) continue;
+        if (jaccardSimilarity(keywords_i, extractKeywords(items[j])) >= SIMILARITY_THRESHOLD) {
+          group.add(j);
+          assigned.add(j);
+        }
+      }
+
+      groups.push(group);
+    }
+
+    return groups.map(group => items[Math.min(...group)]);
+  };
+
   const lines: string[] = [];
   for (const record of records) {
     for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
     for (const limit of record.limits) lines.push(`- limit: ${limit}`);
     for (const warn of record.warns) lines.push(`- warn: ${warn}`);
   }
-  return lines.join("\n");
+
+  return deduplicateBySemanticSimilarity(lines).join("\n");
 };
